    | (UNIV (u, t)) -> (let tmp1 = (FStarC_Options.hide_uvar_nums ()) in
      let x = (if tmp1 then "?" else (let tmp2 = (FStarC_Syntax_Unionfind.univ_uvar_id u) in
        (FStarC_Class_Show.fStarC_Class_Show_show__int tmp2))) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe t) in
      (FStarC_Format.fmt2 "UNIV %s <- %s" x tmp2))
    | (TERM (u, t)) -> (let tmp1 = (FStarC_Options.hide_uvar_nums ()) in
      let x = (if tmp1 then "?" else (let tmp2 = (FStarC_Syntax_Unionfind.uvar_id ((u).FStarC_Syntax_Syntax.ctx_uvar_head, (u).FStarC_Syntax_Syntax.ctx_uvar_head1, (u).FStarC_Syntax_Syntax.ctx_uvar_head2)) in
        (FStarC_Class_Show.fStarC_Class_Show_show__int tmp2))) in
      let tmp2 = (FStarC_TypeChecker_Normalize.term_to_string env t) in
      (FStarC_Format.fmt2 "TERM %s <- %s" x tmp2))
  )

let uvis_to_string (env : FStarC_TypeChecker_Env.env) (l : (uvi) list) : string =
  (FStarC_Common.string_of_list (uvi_to_string env) l)

let occurs (uk : FStarC_Syntax_Syntax.ctx_uvar) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : ((FStarC_Syntax_Syntax.ctx_uvar) list * bool) =
  (let tmp = (FStarC_Syntax_Free.uvars t) in
  let occurs_ = (FStarC_Util.for_some (fun uv -> (FStarC_Syntax_Unionfind.equiv ((uv).FStarC_Syntax_Syntax.ctx_uvar_head, (uv).FStarC_Syntax_Syntax.ctx_uvar_head1, (uv).FStarC_Syntax_Syntax.ctx_uvar_head2) ((uk).FStarC_Syntax_Syntax.ctx_uvar_head, (uk).FStarC_Syntax_Syntax.ctx_uvar_head1, (uk).FStarC_Syntax_Syntax.ctx_uvar_head2))) tmp) in
  (tmp, occurs_))

let set_uvar (env : 'tmp) (u : FStarC_Syntax_Syntax.ctx_uvar) (should_check_opt : (FStarC_Syntax_Syntax.should_check_uvar) option) (t : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : unit =
  ((match should_check_opt with
    | None -> ()
    | (Some (should_check)) -> (let tmp = (FStarC_Syntax_Unionfind.find_decoration ((u).FStarC_Syntax_Syntax.ctx_uvar_head, (u).FStarC_Syntax_Syntax.ctx_uvar_head1, (u).FStarC_Syntax_Syntax.ctx_uvar_head2)) in
      let tmp1 = { FStarC_Syntax_Syntax.uvar_decoration_typ = (tmp).FStarC_Syntax_Syntax.uvar_decoration_typ;
          uvar_decoration_typedness_depends_on = (tmp).FStarC_Syntax_Syntax.uvar_decoration_typedness_depends_on;
          uvar_decoration_should_check = should_check;
          uvar_decoration_should_unrefine = (tmp).FStarC_Syntax_Syntax.uvar_decoration_should_unrefine } in
      (FStarC_Syntax_Unionfind.change_decoration ((u).FStarC_Syntax_Syntax.ctx_uvar_head, (u).FStarC_Syntax_Syntax.ctx_uvar_head1, (u).FStarC_Syntax_Syntax.ctx_uvar_head2) tmp1))
  );
  let tmp = (FStarC_Options.defensive ()) in
  (if tmp then (let tmp1 = (occurs u t) in
  let tmp2 = (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd tmp1) in
  (if tmp2 then (FStarC_Effect.failwith "OCCURS BUG!") else ())) else ());
  (FStarC_Syntax_Util.set_uvar ((u).FStarC_Syntax_Syntax.ctx_uvar_head, (u).FStarC_Syntax_Syntax.ctx_uvar_head1, (u).FStarC_Syntax_Syntax.ctx_uvar_head2) t))

let commit (env : FStarC_TypeChecker_Env.env) (eta : (uvi) list) : unit =
  (FStarC_List.iter (fun tmp -> (match tmp with
    | (UNIV (u, t)) -> (match t with
        | (FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)) -> (FStarC_Syntax_Unionfind.univ_union u (u__1, u__2, u__3))
        | tmp1 -> (FStarC_Syntax_Unionfind.univ_change u t)
      )
    | (TERM (u, t)) -> (let tmp1 = (FStarC_List.map (fun b -> (b).FStarC_Syntax_Syntax.binder_bv) (u).FStarC_Syntax_Syntax.ctx_uvar_binders) in
      (FStarC_Defensive.fStarC_Defensive_def_check_scoped__list_bv_syntax_term' (t).FStarC_Syntax_Syntax.pos "commit" tmp1 t);
      (set_uvar env u None t))
  )) eta)

let extend_universe_solution (pid : Prims.int) (sol : (uvi) list) (wl : worklist) : worklist =
  (let tmp = (!(dbg_Rel)) in
  (if tmp then (let tmp1 = (FStarC_Class_Show.fStarC_Class_Show_show__int pid) in
  let tmp2 = (uvis_to_string (wl).tcenv sol) in
  (FStarC_Format.print2 "Solving %s: with [%s]\n" tmp1 tmp2)) else ());
  (commit (wl).tcenv sol);
  { attempting = (wl).attempting;
    wl_deferred = (wl).wl_deferred;
    wl_deferred_to_tac = (wl).wl_deferred_to_tac;
    ctr = (Prims.op_Plus (wl).ctr (Prims.parse_int "1"));
    defer_ok = (wl).defer_ok;
    smt_ok = (wl).smt_ok;
    umax_heuristic_ok = (wl).umax_heuristic_ok;
    eq_norm_heuristic_ok = (wl).eq_norm_heuristic_ok;
    tcenv = (wl).tcenv;
    wl_implicits = (wl).wl_implicits;
    repr_subcomp_allowed = (wl).repr_subcomp_allowed;
    typeclass_variables = (wl).typeclass_variables })

let rec norm_univ__aux (u : FStarC_Syntax_Syntax.universe) : FStarC_Syntax_Syntax.universe =
  (let u1 = (FStarC_Syntax_Subst.compress_univ u) in
  (match u1 with
    | (FStarC_Syntax_Syntax.U_succ (u2)) -> (let tmp = (norm_univ__aux u2) in
      (FStarC_Syntax_Syntax.U_succ (tmp)))
    | (FStarC_Syntax_Syntax.U_max (us)) -> (let tmp = (FStarC_List.map norm_univ__aux us) in
      (FStarC_Syntax_Syntax.U_max (tmp)))
    | tmp -> u1
  ))

let norm_univ (wl : worklist) (u : FStarC_Syntax_Syntax.universe) : FStarC_Syntax_Syntax.universe =
  (let tmp = (norm_univ__aux u) in
  (FStarC_TypeChecker_Normalize.normalize_universe (wl).tcenv tmp))

let rec solve_universe_eq__aux (pid_orig : Prims.int) (wl : worklist) (us1 : (FStarC_Syntax_Syntax.universe) list) (us2 : (FStarC_Syntax_Syntax.universe) list) : univ_eq_sol =
  (match (us1, us2) with
    | ((u1 :: us11), (u2 :: us21)) -> (let tmp = (solve_universe_eq pid_orig wl u1 u2) in
      (match tmp with
        | (USolved (wl1)) -> ((solve_universe_eq__aux pid_orig) wl1 us11 us21)
        | failed -> failed
      ))
    | tmp -> (USolved (wl))
  )

and fStarC_TypeChecker_Rel_solve_universe_eq__aux__1 (pid_orig : Prims.int) (u' : FStarC_Syntax_Syntax.universe) (wl : worklist) (us : (FStarC_Syntax_Syntax.universe) list) : univ_eq_sol =
  (match us with
    | [] -> (USolved (wl))
    | (u :: us1) -> (let tmp = (solve_universe_eq pid_orig wl u u') in
      (match tmp with
        | (USolved (wl1)) -> ((fStarC_TypeChecker_Rel_solve_universe_eq__aux__1 pid_orig u') wl1 us1)
        | failed -> failed
      ))
  )

and fStarC_TypeChecker_Rel_solve_universe_eq__aux__2 (pid_orig : Prims.int) (u' : FStarC_Syntax_Syntax.universe) (wl : worklist) (us : (FStarC_Syntax_Syntax.universe) list) : univ_eq_sol =
  (match us with
    | [] -> (USolved (wl))
    | (u :: us1) -> (let tmp = (solve_universe_eq pid_orig wl u u') in
      (match tmp with
        | (USolved (wl1)) -> ((fStarC_TypeChecker_Rel_solve_universe_eq__aux__2 pid_orig u') wl1 us1)
        | failed -> failed
      ))
  )

and solve_universe_eq (pid_orig : Prims.int) (wl : worklist) (u1 : FStarC_Syntax_Syntax.universe) (u2 : FStarC_Syntax_Syntax.universe) : univ_eq_sol =
  (let u11 = (FStarC_TypeChecker_Normalize.normalize_universe (wl).tcenv u1) in
  let u21 = (FStarC_TypeChecker_Normalize.normalize_universe (wl).tcenv u2) in
  let try_umax_components = (fun u12 u22 msg -> (if (not (wl).umax_heuristic_ok) then (ufailed_simple "Unable to unify universe terms with umax") else (match (u12, u22) with
      | ((FStarC_Syntax_Syntax.U_max (us1)), (FStarC_Syntax_Syntax.U_max (us2))) -> (let tmp = (solve_universe_eq__filter_out_common_univs us1 us2) in
        (match tmp with
          | (us11, us21) -> (if ((=) (FStarC_List.length us11) (FStarC_List.length us21)) then ((solve_universe_eq__aux pid_orig) wl us11 us21) else (ufailed_thunk (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u12) in
            let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u22) in
            (FStarC_Format.fmt2 "Unable to unify universes: %s and %s" tmp2 tmp3)))))
        ))
      | ((FStarC_Syntax_Syntax.U_max (us)), u') -> ((fStarC_TypeChecker_Rel_solve_universe_eq__aux__1 pid_orig u') wl us)
      | (u', (FStarC_Syntax_Syntax.U_max (us))) -> ((fStarC_TypeChecker_Rel_solve_universe_eq__aux__2 pid_orig u') wl us)
      | tmp -> (ufailed_thunk (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u12) in
        let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u22) in
        (FStarC_Format.fmt3 "Unable to unify universes: %s and %s (%s)" tmp2 tmp3 msg))))
    ))) in
  (match (u11, u21) with
    | ((FStarC_Syntax_Syntax.U_bvar (tmp)), tmp1) -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp4 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp2 tmp3) in
      (FStarC_Effect.failwith tmp4))
    | (FStarC_Syntax_Syntax.U_unknown, tmp) -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp3 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp1 tmp2) in
      (FStarC_Effect.failwith tmp3))
    | (tmp, (FStarC_Syntax_Syntax.U_bvar (tmp1))) -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp4 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp2 tmp3) in
      (FStarC_Effect.failwith tmp4))
    | (tmp, FStarC_Syntax_Syntax.U_unknown) -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp3 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp1 tmp2) in
      (FStarC_Effect.failwith tmp3))
    | ((FStarC_Syntax_Syntax.U_name (x)), (FStarC_Syntax_Syntax.U_name (y))) -> (if ((=) (FStarC_Ident.string_of_id x) (FStarC_Ident.string_of_id y)) then (USolved (wl)) else (ufailed_simple "Incompatible universes"))
    | (FStarC_Syntax_Syntax.U_zero, FStarC_Syntax_Syntax.U_zero) -> (USolved (wl))
    | ((FStarC_Syntax_Syntax.U_succ (u12)), (FStarC_Syntax_Syntax.U_succ (u22))) -> (solve_universe_eq pid_orig wl u12 u22)
    | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), (FStarC_Syntax_Syntax.U_unif (u__11, u__21, u__31))) -> (let v1 = (u__1, u__2, u__3) in
      let tmp = (FStarC_Syntax_Unionfind.univ_equiv v1 (u__11, u__21, u__31)) in
      (if tmp then (USolved (wl)) else (let wl1 = (extend_universe_solution pid_orig ((UNIV (v1, u21)) :: []) wl) in
      (USolved (wl1)))))
    | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), u) -> (let v1 = (u__1, u__2, u__3) in
      let u3 = (norm_univ wl u) in
      let tmp = (solve_universe_eq__occurs_univ v1 u3) in
      (if tmp then (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe (FStarC_Syntax_Syntax.U_unif ((match v1 with (custard_tup, _, _) -> custard_tup), (match v1 with (_, custard_tup, _) -> custard_tup), (match v1 with (_, _, custard_tup) -> custard_tup)))) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u3) in
      let tmp3 = (FStarC_Format.fmt2 "Failed occurs check: %s occurs in %s" tmp1 tmp2) in
      (try_umax_components u11 u21 tmp3)) else (let tmp1 = (extend_universe_solution pid_orig ((UNIV (v1, u3)) :: []) wl) in
      (USolved (tmp1)))))
    | (u, (FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3))) -> (let v1 = (u__1, u__2, u__3) in
      let u3 = (norm_univ wl u) in
      let tmp = (solve_universe_eq__occurs_univ v1 u3) in
      (if tmp then (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe (FStarC_Syntax_Syntax.U_unif ((match v1 with (custard_tup, _, _) -> custard_tup), (match v1 with (_, custard_tup, _) -> custard_tup), (match v1 with (_, _, custard_tup) -> custard_tup)))) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u3) in
      let tmp3 = (FStarC_Format.fmt2 "Failed occurs check: %s occurs in %s" tmp1 tmp2) in
      (try_umax_components u11 u21 tmp3)) else (let tmp1 = (extend_universe_solution pid_orig ((UNIV (v1, u3)) :: []) wl) in
      (USolved (tmp1)))))
    | ((FStarC_Syntax_Syntax.U_max (tmp)), tmp1) -> (if ((=) (wl).defer_ok DeferAny) then (UDeferred (wl)) else (let u12 = (norm_univ wl u11) in
      let u22 = (norm_univ wl u21) in
      let tmp2 = (FStarC_Syntax_Util.eq_univs u12 u22) in
      (if tmp2 then (USolved (wl)) else (try_umax_components u12 u22 ""))))
    | (tmp, (FStarC_Syntax_Syntax.U_max (tmp1))) -> (if ((=) (wl).defer_ok DeferAny) then (UDeferred (wl)) else (let u12 = (norm_univ wl u11) in
      let u22 = (norm_univ wl u21) in
      let tmp2 = (FStarC_Syntax_Util.eq_univs u12 u22) in
      (if tmp2 then (USolved (wl)) else (try_umax_components u12 u22 ""))))
    | ((FStarC_Syntax_Syntax.U_succ (tmp)), FStarC_Syntax_Syntax.U_zero) -> (ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_succ (tmp)), (FStarC_Syntax_Syntax.U_name (tmp1))) -> (ufailed_simple "Incompatible universes")
    | (FStarC_Syntax_Syntax.U_zero, (FStarC_Syntax_Syntax.U_succ (tmp))) -> (ufailed_simple "Incompatible universes")
    | (FStarC_Syntax_Syntax.U_zero, (FStarC_Syntax_Syntax.U_name (tmp))) -> (ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_name (tmp)), (FStarC_Syntax_Syntax.U_succ (tmp1))) -> (ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_name (tmp)), FStarC_Syntax_Syntax.U_zero) -> (ufailed_simple "Incompatible universes")
  ))

let rec solve_universe_inequalities'__check_ineq (env : FStarC_TypeChecker_Env.env) (p : (FStarC_Syntax_Syntax.universe * FStarC_Syntax_Syntax.universe)) : bool =
  (match p with
    | (u, v) -> (let u1 = (FStarC_TypeChecker_Normalize.normalize_universe env u) in
      let v1 = (FStarC_TypeChecker_Normalize.normalize_universe env v) in
      (match (u1, v1) with
        | (FStarC_Syntax_Syntax.U_zero, tmp) -> true
        | ((FStarC_Syntax_Syntax.U_succ (u0)), (FStarC_Syntax_Syntax.U_succ (v0))) -> ((solve_universe_inequalities'__check_ineq env) (u0, v0))
        | ((FStarC_Syntax_Syntax.U_name (u0)), (FStarC_Syntax_Syntax.U_name (v0))) -> (FStarC_Ident.ident_equals u0 v0)
        | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), (FStarC_Syntax_Syntax.U_unif (u__11, u__21, u__31))) -> (FStarC_Syntax_Unionfind.univ_equiv (u__1, u__2, u__3) (u__11, u__21, u__31))
        | ((FStarC_Syntax_Syntax.U_name (tmp)), (FStarC_Syntax_Syntax.U_succ (v0))) -> ((solve_universe_inequalities'__check_ineq env) (u1, v0))
        | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), (FStarC_Syntax_Syntax.U_succ (v0))) -> ((solve_universe_inequalities'__check_ineq env) (u1, v0))
        | ((FStarC_Syntax_Syntax.U_max (us)), tmp) -> (FStarC_Util.for_all (fun u2 -> ((solve_universe_inequalities'__check_ineq env) (u2, v1))) us)
        | (tmp, (FStarC_Syntax_Syntax.U_max (vs))) -> (FStarC_Util.for_some (fun v2 -> ((solve_universe_inequalities'__check_ineq env) (u1, v2))) vs)
        | tmp -> false
      ))
  )

let dbg_GenUniverses : (bool ref) =
  (FStarC_Debug.get_toggle "GenUniverses")

let ineqs_to_string (ineqs : ((FStarC_Syntax_Syntax.universe) FStarC_CList.clist * ((FStarC_Syntax_Syntax.universe * FStarC_Syntax_Syntax.universe)) FStarC_CList.clist)) : string =
  (match ineqs with
    | (vars, ineqs1) -> (let ineqs2 = (FStarC_CList.map (fun tmp -> (match tmp with
          | (u1, u2) -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u1) in
            let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u2) in
            (FStarC_Format.fmt2 "%s < %s" tmp1 tmp2))
        )) ineqs1) in
      let tmp = (FStarC_Syntax_Print.fStarC_Class_Show_show__clist_universe vars) in
      let tmp1 = (FStarC_CList.fStarC_Class_Show_show__clist_string ineqs2) in
      (FStarC_Format.fmt2 "Solving for %s; inequalities are %s" tmp tmp1))
  )

let solve_universe_inequalities' (tx : FStarC_Syntax_Unionfind.uf) (env : FStarC_TypeChecker_Env.env) (vs_ineqs : ((FStarC_Syntax_Syntax.universe) FStarC_CList.clist * ((FStarC_Syntax_Syntax.universe * FStarC_Syntax_Syntax.universe)) FStarC_CList.clist)) : unit =
  (match vs_ineqs with
    | (variables, ineqs) -> (let fail = (fun u1 u2 -> ((FStarC_Syntax_Unionfind.rollback tx);
        let tmp = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u1) in
        let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u2) in
        let tmp2 = (FStarC_Format.fmt2 "Universe %s and %s are incompatible" tmp tmp1) in
        (FStarC_TypeChecker_Env.fStarC_Errors_raise_error__env_string env FStarC_Errors_Codes.Fatal_IncompatibleUniverse tmp2))) in
      let equiv = (fun v v' -> (let tmp = (FStarC_Syntax_Subst.compress_univ v) in
        let tmp1 = (FStarC_Syntax_Subst.compress_univ v') in
        let tmp2 = (tmp, tmp1) in
        (match tmp2 with
          | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), (FStarC_Syntax_Syntax.U_unif (u__11, u__21, u__31))) -> (FStarC_Syntax_Unionfind.univ_equiv (u__1, u__2, u__3) (u__11, u__21, u__31))
          | tmp3 -> false
        ))) in
      let sols = (FStarC_CList.collect (fun v -> (let tmp = (FStarC_Syntax_Subst.compress_univ v) in
        (match tmp with
          | (FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)) -> (let lower_bounds_of_v = (FStarC_CList.collect (fun tmp1 -> (match tmp1 with
                | (u, v') -> (let tmp2 = (equiv v v') in
                  (if tmp2 then (let tmp3 = (FStarC_CList.existsb (equiv u) variables) in
                  (if tmp3 then FStarC_CList.fStarC_Class_Listlike_empty__universe_clist_universe else (FStarC_CList.fStarC_Class_Listlike_cons__universe_clist_universe u FStarC_CList.fStarC_Class_Listlike_empty__universe_clist_universe))) else FStarC_CList.fStarC_Class_Listlike_empty__universe_clist_universe))
              )) ineqs) in
            let tmp1 = (FStarC_CList.fStarC_Class_Listlike_to_list__universe_clist_universe lower_bounds_of_v) in
            let tmp2 = (FStarC_Syntax_Syntax.U_max (tmp1)) in
            let lb = (FStarC_TypeChecker_Normalize.normalize_universe env tmp2) in
            (FStarC_CList.fStarC_Class_Listlike_singleton__tuple2_universe_universe (lb, v)))
          | tmp1 -> FStarC_CList.fStarC_Class_Listlike_empty__tuple2_universe_universe
        ))) variables) in
      let tmp = (empty_worklist env) in
      let wl = { attempting = (tmp).attempting;
          wl_deferred = (tmp).wl_deferred;
          wl_deferred_to_tac = (tmp).wl_deferred_to_tac;
          ctr = (tmp).ctr;
          defer_ok = NoDefer;
          smt_ok = (tmp).smt_ok;
          umax_heuristic_ok = (tmp).umax_heuristic_ok;
          eq_norm_heuristic_ok = (tmp).eq_norm_heuristic_ok;
          tcenv = (tmp).tcenv;
          wl_implicits = (tmp).wl_implicits;
          repr_subcomp_allowed = (tmp).repr_subcomp_allowed;
          typeclass_variables = (tmp).typeclass_variables } in
      (ignore (FStarC_CList.map (fun tmp1 -> (match tmp1 with
        | (lb, v) -> (let tmp2 = (solve_universe_eq (Prims.parse_int "-1") wl lb v) in
          (match tmp2 with
            | (USolved (wl1)) -> ()
            | tmp3 -> (fail lb v)
          ))
      )) sols));
      let tmp1 = (FStarC_CList.for_all (fun tmp1 -> (match tmp1 with
          | (u, v) -> (let tmp2 = ((solve_universe_inequalities'__check_ineq env) (u, v)) in
            (if tmp2 then true else (let tmp3 = (!(dbg_GenUniverses)) in
            (if tmp3 then (let tmp4 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u) in
            let tmp5 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe v) in
            (FStarC_Format.print2 "%s </= %s" tmp4 tmp5)) else ());
            false)))
        )) ineqs) in
      (if tmp1 then () else (let tmp2 = (!(dbg_GenUniverses)) in
      (if tmp2 then (let tmp3 = (ineqs_to_string (variables, ineqs)) in
