  let tmp1 = (tmp).FStarC_Syntax_Syntax.n in
  (match tmp1 with
    | (FStarC_Syntax_Syntax.Tm_name (tmp2)) -> true
    | (FStarC_Syntax_Syntax.Tm_match (tmp2)) -> true
