  (match tmp with
    | FStarC_TypeChecker_Common.Rigid_rigid -> (Prims.parse_int "0")
    | FStarC_TypeChecker_Common.Flex_rigid_eq -> (Prims.parse_int "1")
    | FStarC_TypeChecker_Common.Flex_flex_pattern_eq -> (Prims.parse_int "2")
