let solve_prob' (resolve_ok : bool) (prob : FStarC_TypeChecker_Common.prob) (logical_guard : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) option) (uvis : (uvi) list) (wl : worklist) : worklist =
