  (commit (wl1).tcenv uvis);
  { attempting = (wl1).attempting;
    wl_deferred = (wl1).wl_deferred;
    wl_deferred_to_tac = (wl1).wl_deferred_to_tac;
    ctr = (Prims.op_Plus (wl1).ctr (Prims.parse_int "1"));
