  let tmp = (mk_problem wl scope orig lhs rel rhs elt reason) in
  (match tmp with
    | (p, wl1) -> ((def_check_prob (Prims.strcat reason ".mk_t") (FStarC_TypeChecker_Common.TProb (p)));
      ((FStarC_TypeChecker_Common.TProb (p)), wl1))
  ))

